import{c as t,J as a,h as o,k as n}from"./chunks/framework.WgZQdPFo.js";const u=JSON.parse('{"title":"Capital Overview & Philosophy","description":"Unified personal finance contour for master craftsmen, separating workshop cash from personal funds, and automated expense tracking via balance delta.","frontmatter":{"title":"Capital Overview & Philosophy","description":"Unified personal finance contour for master craftsmen, separating workshop cash from personal funds, and automated expense tracking via balance delta.","order":16},"headers":[],"relativePath":"docs/spaces/moy-kapital/overview.md","filePath":"docs/spaces/moy-kapital/overview.md"}'),s={name:"docs/spaces/moy-kapital/overview.md"};function r(i,e,l,c,p,d){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="capital-overview-philosophy" tabindex="-1">Capital Overview &amp; Philosophy <a class="header-anchor" href="#capital-overview-philosophy" aria-label="Permalink to &quot;Capital Overview &amp; Philosophy&quot;">​</a></h1><p>Every craft workshop owner and maker eventually faces the same fundamental dilemma: where does the workshop&#39;s money end and personal family finances begin?</p><p>Mixing leather or wood purchases, workshop rent, and personal grocery bills in a single bank account destroys financial visibility. It becomes impossible to tell whether the business generates genuine net profit or merely stays afloat through continuous personal subsidies.</p><p>The <strong>My Capital</strong> workspace in OmniCraft ERP PRO mode resolves this challenge by establishing a strict, automated boundary between business operations and personal wealth—without forcing you to become an exhausted bookkeeper collecting supermarket receipts.</p><hr><h2 id="two-contour-principle-workshop-cash-vs-maker-s-pocket" tabindex="-1">Two-Contour Principle: Workshop Cash vs. Maker&#39;s Pocket <a class="header-anchor" href="#two-contour-principle-workshop-cash-vs-maker-s-pocket" aria-label="Permalink to &quot;Two-Contour Principle: Workshop Cash vs. Maker&#39;s Pocket&quot;">​</a></h2><p>The financial architecture of OmniCraft ERP separates money flows into two distinct contours:</p><ol><li><strong>Workshop Operational Contour (Production Workspaces):</strong> raw materials inventory, cost calculation, work in progress on the workbench, cash flow ledger (DDS), and finished goods showcase.</li><li><strong>Consolidated Capital Contour (My Capital Workspace):</strong> the total net worth of the owner, including personal bank accounts, savings, investment portfolios, equipment, real estate, and equity in each production workspace.</li></ol><div class="info custom-block"><p class="custom-block-title">Database Isolation</p><p>Personal finances are stored in a dedicated, isolated database file <code>personal_finance.db</code>. Your personal bank accounts, investments, and private assets never leak into production reports and remain strictly confidential.</p></div><hr><h2 id="mathematical-delta-automated-expenses-without-receipt-tracking" tabindex="-1">Mathematical Delta: Automated Expenses Without Receipt Tracking <a class="header-anchor" href="#mathematical-delta-automated-expenses-without-receipt-tracking" aria-label="Permalink to &quot;Mathematical Delta: Automated Expenses Without Receipt Tracking&quot;">​</a></h2><p>The core engineering breakthrough of My Capital is the <strong>Balance Delta expense calculation method</strong>.</p><p>Most personal finance apps demand robotic discipline: entering every coffee, fuel, and meal expense manually every single day. In reality, craftsmen abandon this routine within two weeks.</p><p>OmniCraft ERP applies an inverted engineering approach:</p><p>$$\\text{Personal Expenses} = \\text{Initial Capital} + \\text{Workshop Profit &amp; Personal Income} - \\text{Ending Capital}$$</p><p>You simply update account balances once a week or at month-end. The program automatically balances the delta against workshop operations and calculates the exact amount spent on personal life.</p><div class="tip custom-block"><p class="custom-block-title">Peace of Mind</p><p>If personal bank balances increase over the month while workshop net profit is confirmed by finished goods sales, your business is genuinely thriving. If balances deplete, the system highlights the unallocated outflow before a cash flow crisis occurs.</p></div><hr><h2 id="architecture-of-my-capital" tabindex="-1">Architecture of My Capital <a class="header-anchor" href="#architecture-of-my-capital" aria-label="Permalink to &quot;Architecture of My Capital&quot;">​</a></h2><p>The workspace interface is structured into a streamlined 5-step funnel:</p><ul><li><strong>Accounts &amp; Investments:</strong> central hub for liquid funds. Houses two sub-tabs: &quot;Accounts &amp; Wallets&quot; (cash, cards, deposits, multi-currency, and stablecoins) and &quot;Investment Portfolio&quot; (stocks, bonds, loans, business equity).</li><li><strong>Property &amp; Resources:</strong> long-term physical assets outside production (specialized machinery, vehicles, workshop premises).</li><li><strong>Personal Operations:</strong> ledger of significant personal income and major capital expenditures.</li><li><strong>Capital Dashboard:</strong> Net Worth command center combining personal holdings and production capital across all connected workspaces.</li><li><strong>Capital Analytics:</strong> long-term wealth growth charts, currency basket distribution, and asset class balancing.</li></ul><hr><h2 id="top-level-action-toolbar" tabindex="-1">Top-Level Action Toolbar <a class="header-anchor" href="#top-level-action-toolbar" aria-label="Permalink to &quot;Top-Level Action Toolbar&quot;">​</a></h2><p>The upper-right toolbar in My Capital provides quick access to core utilities:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Button</th><th style="text-align:left;">Purpose</th><th style="text-align:left;">Action</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>📊 Statistics</strong></td><td style="text-align:left;">Asset Structure &amp; Allocation</td><td style="text-align:left;">Opens a side drawer or modal dialog with stacked charts of the currency basket and asset classes.</td></tr><tr><td style="text-align:left;"><strong>💱 Rates</strong></td><td style="text-align:left;">Centralized Currency Directory</td><td style="text-align:left;">One-click inline editing of exchange rates or instant AI prompt import without paid external APIs.</td></tr><tr><td style="text-align:left;"><strong>⚙️ Settings</strong></td><td style="text-align:left;">Workspace Configuration</td><td style="text-align:left;">Select between side drawer or modal dialog for statistics, manage account types and categories.</td></tr><tr><td style="text-align:left;"><strong>📖 Docs</strong></td><td style="text-align:left;">Contextual Documentation</td><td style="text-align:left;">Instantly opens the exact documentation page matching your currently active tab.</td></tr></tbody></table><hr><h2 id="privacy-zero-api-dependency" tabindex="-1">Privacy &amp; Zero-API Dependency <a class="header-anchor" href="#privacy-zero-api-dependency" aria-label="Permalink to &quot;Privacy &amp; Zero-API Dependency&quot;">​</a></h2><p>All financial calculations happen <strong>strictly offline on your local computer</strong>. OmniCraft ERP never transmits your balances, investments, or bank credentials to third-party clouds or tracking servers. Currency rates update seamlessly without recurring API fees: you can edit rates manually in seconds or copy an AI prompt to any free language model and paste the result with one click.</p>',28)])])}const m=t(s,[["render",r]]);export{u as __pageData,m as default};
